window.bookSummaryJSON = "<p></p><p>FNH Audio presents an unabridged recording of <i>The Living Mummy</i>.</p><p></p> <p></p><p>Dr Pisent is in the desert of Egypt unearthing ancient remains when Sir Robert Otterly, another Egyptologist, enters the camp seeking help. This is the start of an occult adventure spanning continents, that includes murder, torture, spells, and mysteries.</p><p></p>"; 
